                uBass:             { value: 0 },
                uLowMid:           { value: 0 },
                uMid:              { value: 0 },
                uHighMid:          { value: 0 },
                uHigh:             { value: 0 },
                uUltraHigh:        { value: 0 },
                uBeatEnergy:       { value: 0 },
                uSpectralCentroid: { value: 0 },
                uSpectralFlux:     { value: 0 },
                uOnsetEnergy:      { value: 0 },
                uVortexStrength:   { value: STATE.vortexStrength },
                uColor1:           { value: new THREE.Color(def.sc1) },
                uColor2:           { value: new THREE.Color(def.sc2) },
